import json
import math

def residual(a, b):
    return a * math.sqrt(1 - b * b) - b * math.sqrt(1 - a * a) - 1.0

# Derived parametrization: a = sin x, b = sin y with x - y = pi/2, giving
# a = cos y, b = sin y for y in [-pi/2, 0]. Check it on a finite grid of y values.
witnesses = []
N = 200
for k in range(N + 1):
    y = -math.pi / 2 + k * (math.pi / 2) / N
    a = max(-1.0, min(1.0, math.cos(y)))
    b = max(-1.0, min(1.0, math.sin(y)))
    if -1.0 <= a <= 1.0 and -1.0 <= b <= 1.0 and abs(residual(a, b)) < 1e-9:
        witnesses.append((a, b, round(a * a - b * b, 9)))

distinct_D = sorted(set(w[2] for w in witnesses))

if len(distinct_D) > 1:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {
            "constraint": "a*sqrt(1-b^2) - b*sqrt(1-a^2) = 1 with -1<=a,b<=1",
            "witness_count": len(witnesses),
            "distinct_D_values": distinct_D,
            "example_points": [
                {"a": round(w[0], 9), "b": round(w[1], 9), "D": w[2]}
                for w in (witnesses[0], witnesses[-1])
            ],
            "reason": "D = cos(2y) takes multiple values on the solution set, so D is not determined.",
        },
    }
else:
    result = {
        "final_answer": str(distinct_D[0]) if distinct_D else "UNSUPPORTED",
        "evidence": {"witness_count": len(witnesses), "distinct_D_values": distinct_D},
    }

print(json.dumps(result))
